<?php
declare(strict_types=1);

// Test generated by Claude Code (with manual adjustments).

namespace Tests\Store\Action\Query;

use Module\Store\Action\Query\CheckStoreExistsQry;
use Module\Store\Model\Store;
use Module\Store\Model\StoreRepository;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class CheckStoreExistsQryTest extends IntegrationTestCase
{
    private CheckStoreExistsQry $sut;

    private StoreRepository $repository;

    public function setUp(): void
    {
        parent::setUp();

        $this->repository = $this->container->get(StoreRepository::class);
        $this->sut = new CheckStoreExistsQry($this->repository);
        $this->prepareDb();
    }

    #[Test, DataProvider('dataProviderCheck')]
    public function check(
        int $storeId,
        bool $expected,
    ): void {
        $result = $this->sut->check($storeId);

        $this->assertSame($expected, $result);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderCheck(): array
    {
        return [
            'exists' => [
                'storeId' => 10,
                'expected' => true,
            ],
            'not found' => [
                'storeId' => 99,
                'expected' => false,
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->repository->saveWithId(Store::factory('EXT-10', 'Test Store', '123 Main St', 10));
        $this->repository->flush();
    }
}
